function flagFor(config, userId) {
  if (config.userIds.includes(userId)) return true;
  return config.default;
}

function isOn(config, userId) {
  if (config.killSwitch) return false;
  if (config.userIds.includes(userId)) return true;
  return config.default;
}

function firstMatch(rules, userId, fallback) {
  for (const rule of rules) {
    if (rule.userIds.includes(userId)) return rule.serve;
  }
  return fallback;
}

function inRollout(bucket, percent) {
  return bucket < percent;
}

function evaluate(config, ctx) {
  if (config.killSwitch) return { enabled: false, reason: "kill-switch" };
  for (const rule of config.rules) {
    if (rule.type === "userIdIn" && rule.values.includes(ctx.userId)) {
      return { enabled: rule.serve, reason: rule.type };
    }
    if (rule.type === "planTier" && rule.values.includes(ctx.planTier)) {
      return { enabled: rule.serve, reason: rule.type };
    }
  }
  return { enabled: config.default, reason: "default" };
}

function evaluateRollout(config, ctx) {
  if (config.killSwitch) return { enabled: false, reason: "kill-switch" };
  for (const rule of config.rules) {
    if (rule.type === "userIdIn" && rule.values.includes(ctx.userId)) {
      return { enabled: rule.serve, reason: rule.type };
    }
    if (rule.type === "percentageRollout" && ctx.bucket < rule.percent) {
      return { enabled: rule.serve, reason: rule.type };
    }
  }
  return { enabled: config.default, reason: "default" };
}

function insertBeforeRollout(rules, rule) {
  const index = rules.findIndex((r) => r.type === "percentageRollout");
  const copy = rules.slice();
  copy.splice(index === -1 ? copy.length : index, 0, rule);
  return copy;
}
